package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** One of the sheet's periods: a name unique on the sheet and a from and to date, both inclusive. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The name as uniqueness compares it: trimmed and lower-cased. */
    @Column(name = "name_key", nullable = false)
    private String nameKey;

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    @Column(name = "to_date", nullable = false)
    private LocalDate to;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether the period is soft-closed: its figures are fixed, but its claims can still change. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** Whether a steward has locked the period: a locked period cannot be reopened. */
    @Column(name = "locked", nullable = false)
    private boolean locked;

    /** The due-total fixed when the period was closed or soft-closed; null while it is open. */
    @Column(name = "closed_total")
    private BigDecimal closedTotal;

    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", nullable = false)
    private Map<Long, BigDecimal> closedPersonTotals = new HashMap<>();

    /** Each person's carried figure fixed when the period was closed or soft-closed, by person id; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", nullable = false)
    private Map<Long, BigDecimal> closedPersonCarried = new HashMap<>();

    /** Every pool member's cut fixed when the period was closed or soft-closed; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_pool_cut", joinColumns = @JoinColumn(name = "period_id"))
    private Set<PeriodPoolCut> closedPoolCuts = new HashSet<>();

    /** Each person's opening balance for the period, by person id: part of their carried figure for it. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_opening", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "amount", nullable = false)
    private Map<Long, BigDecimal> personOpenings = new HashMap<>();

    /** How many OPEN or PENDING claims a person may have in the period; null for no cap. */
    @Column(name = "claim_cap")
    private Integer cap;

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this.sheetId = sheetId;
        this.name = name.trim();
        this.nameKey = keyOf(name);
        this.from = from;
        this.to = to;
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
        this(sheetId, name, from, to);
        this.cap = cap;
    }

    /** The name as uniqueness compares it. */
    public static String keyOf(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public String getNameKey() {
        return nameKey;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    public Integer getCap() {
        return cap;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    public boolean isLocked() {
        return locked;
    }

    public void setLocked(boolean locked) {
        this.locked = locked;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getClosedPersonTotals() {
        return closedPersonTotals;
    }

    public Map<Long, BigDecimal> getClosedPersonCarried() {
        return closedPersonCarried;
    }

    /** Each pool member's cut fixed when the period was closed or soft-closed, by member key, by pool id (a
     *  crew's negated); a pool that showed no cuts then is missing; empty while it is open. */
    public Map<Long, Map<String, BigDecimal>> getClosedPoolCuts() {
        Map<Long, Map<String, BigDecimal>> byPool = new HashMap<>();
        for (PeriodPoolCut c : closedPoolCuts) {
            byPool.computeIfAbsent(c.getPoolId(), (id) -> new HashMap<>()).put(c.getMemberKey(), c.getCut());
        }
        return byPool;
    }

    /** Fix every pool member's cut for the period, by member key, by pool id, as worked out now. */
    public void fixPoolCuts(Map<Long, Map<String, BigDecimal>> cuts) {
        closedPoolCuts.clear();
        cuts.forEach((poolId, members) -> members.forEach((key, cut) ->
                closedPoolCuts.add(new PeriodPoolCut(poolId, key, cut))));
    }

    public Map<Long, BigDecimal> getPersonOpenings() {
        return personOpenings;
    }

    /** The person's opening balance for the period; 0.00 when none was set. */
    public BigDecimal openingOf(Long personId) {
        return personOpenings.getOrDefault(personId, BigDecimal.ZERO.setScale(2));
    }

    /** Add the amount to the person's opening balance for the period. */
    public void addOpening(Long personId, BigDecimal amount) {
        personOpenings.merge(personId, amount.setScale(2), BigDecimal::add);
    }

    /** Close the period, fixing its due-total and each person's due-total and carried figure for it, by person id. */
    public void close(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        fix(total, personTotals, personCarried);
        this.closed = true;
    }

    /** Soft-close the period, fixing its figures as a close does while its claims can still change. */
    public void softClose(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        fix(total, personTotals, personCarried);
        this.softClosed = true;
    }

    private void fix(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried) {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = total;
        this.closedPersonTotals.clear();
        this.closedPersonTotals.putAll(personTotals);
        this.closedPersonCarried.clear();
        this.closedPersonCarried.putAll(personCarried);
    }

    /** Reopen the period: its due-total and carried figures are live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.closedPersonTotals.clear();
        this.closedPersonCarried.clear();
        this.closedPoolCuts.clear();
    }

    /** Whether the date falls within this period, both ends inclusive. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }

    /** Whether this period shares a day with the dates from and to, both inclusive. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !this.from.isAfter(to) && !from.isAfter(this.to);
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface PeriodRepository extends JpaRepository<Period, Long> {

    /** The sheet's periods in date order. */
    List<Period> findBySheetIdOrderByFromAsc(String sheetId);

    Optional<Period> findByIdAndSheetId(Long id, String sheetId);

    boolean existsBySheetIdAndNameKey(String sheetId, String nameKey);

    /** Whether the date falls within one of the sheet's closed periods. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.closed = true"
            + " and p.from <= :date and p.to >= :date")
    boolean isClosedOn(@Param("sheetId") String sheetId, @Param("date") LocalDate date);

    /** Whether the date falls within one of the sheet's soft-closed periods. */
    @Query("select count(p) > 0 from Period p where p.sheetId = :sheetId and p.softClosed = true"
            + " and p.from <= :date and p.to >= :date")
    boolean isSoftClosedOn(@Param("sheetId") String sheetId, @Param("date") LocalDate date);
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';

export interface PeriodView {
  id: number;
  name: string;
  /** The first day of the period (yyyy-mm-dd), inclusive. */
  from: string;
  /** The last day of the period (yyyy-mm-dd), inclusive. */
  to: string;
  /** Whether the period is closed: no claim dated in it can then change. */
  closed: boolean;
  /** Whether the period is soft-closed: its figures are fixed, but claims dated in it can still change. */
  softClosed: boolean;
  /** The due-total fixed when the period was closed or soft-closed, with two decimals; null while it is open. */
  closedTotal: string | null;
  /** Each person's due-total fixed when the period was closed, with two decimals, by person id; empty
   *  while it is open. A person missing from it (added after the close) has 0.00. */
  closedPersonTotals: Record<string, string>;
  /** How many OPEN or PENDING claims each person may have in the period; null for no cap. */
  cap: number | null;
  /** Each person's carried figure fixed when the period was closed or soft-closed, with two decimals, by
   *  person id; empty while it is open. A person missing from it (added after the close) has 0.00. */
  closedPersonCarried: Record<string, string>;
  /** Each person's opening balance for the period, with two decimals, by person id: part of their carried
   *  figure for it. A person missing from it has none. */
  personOpenings: Record<string, string>;
  /** Whether a steward has locked the period: a locked period cannot be reopened. */
  locked: boolean;
  /** Each pool member's cut fixed when the period was closed or soft-closed, with two decimals, by member
   *  key, by pool id (a crew's negated); a pool that showed no cuts then is missing. Empty while it is open. */
  closedPoolCuts: Record<string, Record<string, string>>;
}

/** What pasting opening balances did: how many lines went through, and the sheet's periods now. */
export interface OpeningsView {
  added: number;
  periods: PeriodView[];
}

/** What a rollover did: how many periods it made, and the sheet's periods now. */
export interface RolloverView {
  made: number;
  periods: PeriodView[];
}

export interface PeriodForm {
  name: string;
  from: string;
  to: string;
  /** The cap on each person's open claims in the period; null for none. */
  cap: number | null;
}

/** The period whose dates contain the date, or null when none does; periods never overlap. */
export function periodOf(periods: readonly PeriodView[], date: string): PeriodView | null {
  return periods.find((p) => p.from <= date && date <= p.to) ?? null;
}

// The periods of a sheet, as the store holds them.
@Injectable({ providedIn: 'root' })
export class PeriodsApi {
  private readonly http = inject(HttpClient);

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/periods`;
  }

  /** The sheet's periods in date order. */
  list(sheetId: string): Promise<PeriodView[]> {
    return firstValueFrom(this.http.get<PeriodView[]>(this.url(sheetId)));
  }

  /** Add a period: refused when its name is in use, its to-date is before its from-date, or it
   *  overlaps another period. */
  add(sheetId: string, form: PeriodForm): Promise<PeriodView> {
    return firstValueFrom(this.http.post<PeriodView>(this.url(sheetId), form));
  }

  /** Generate one period per calendar month between two dates (a blank one is the sheet's today),
   *  leaving out months whose name is in use or that overlap a period: the periods made. Refused
   *  when the to-date is before the from-date. */
  generate(sheetId: string, from: string | null, to: string | null): Promise<PeriodView[]> {
    return firstValueFrom(this.http.post<PeriodView[]>(`${this.url(sheetId)}/generate`, { from, to }));
  }

  /** Generate the twelve monthly periods of the fiscal year starting in a calendar year, as the monthly
   *  generator does: the periods made. */
  generateFiscalYear(sheetId: string, year: number): Promise<PeriodView[]> {
    return firstValueFrom(this.http.post<PeriodView[]>(`${this.url(sheetId)}/generate-fy`, { year }));
  }

  /** Roll the fiscal year starting in a calendar year over: generate the next fiscal year's periods and
   *  carry each person's open figure into its first period. Refused unless the user is a steward, and when
   *  the year has no periods. */
  rollover(sheetId: string, year: number): Promise<RolloverView> {
    return firstValueFrom(this.http.post<RolloverView>(`${this.url(sheetId)}/rollover`, { year }));
  }

  /** Generate the four calendar quarters of a year, named yyyy-Q1 to yyyy-Q4, leaving out those whose
   *  name is in use or that overlap a period: the periods made. */
  generateQuarters(sheetId: string, year: number): Promise<PeriodView[]> {
    return firstValueFrom(this.http.post<PeriodView[]>(`${this.url(sheetId)}/generate-quarters`, { year }));
  }

  /** Add each pasted line of name,period,amount to the person's opening balance for the period, all or
   *  none: refused when any line names no person or period on the sheet, or its amount is not 0.00 or more
   *  with two decimals. */
  pasteOpenings(sheetId: string, text: string): Promise<OpeningsView> {
    return firstValueFrom(this.http.post<OpeningsView>(`${this.url(sheetId)}/openings`, { text }));
  }

  /** Close a period, fixing its due-total: refused when it is already closed. */
  close(sheetId: string, id: number): Promise<PeriodView> {
    return firstValueFrom(this.http.post<PeriodView>(`${this.url(sheetId)}/${id}/close`, {}));
  }

  /** Soft-close a period, fixing its figures while its claims can still change: refused when it is
   *  closed or soft-closed already. */
  softClose(sheetId: string, id: number): Promise<PeriodView> {
    return firstValueFrom(this.http.post<PeriodView>(`${this.url(sheetId)}/${id}/soft-close`, {}));
  }

  /** Reopen a closed or soft-closed period, making its due-total live again: refused unless the user
   *  is a steward and the period is closed or soft-closed. */
  reopen(sheetId: string, id: number): Promise<PeriodView> {
    return firstValueFrom(this.http.post<PeriodView>(`${this.url(sheetId)}/${id}/reopen`, {}));
  }

  /** Lock a period so it cannot be reopened: refused unless the user is a steward and the period is not locked. */
  lock(sheetId: string, id: number): Promise<PeriodView> {
    return firstValueFrom(this.http.post<PeriodView>(`${this.url(sheetId)}/${id}/lock`, {}));
  }

  /** Unlock a locked period: refused unless the user is a steward and the period is locked. */
  unlock(sheetId: string, id: number): Promise<PeriodView> {
    return firstValueFrom(this.http.post<PeriodView>(`${this.url(sheetId)}/${id}/unlock`, {}));
